teachingContent.beginner:
The **fs** module lets you work with files.

**Reading a File:**
```javascript
const fs = require('fs');

fs.readFile('data.txt', 'utf8', (err, data) => {
  if (err) {
    console.error(err);
    return;
  }
  console.log(data);
});
```

**Writing a File:**
```javascript
fs.writeFile('output.txt', 'Hello!', (err) => {
  if (err) throw err;
  console.log('File saved!');
});
```

teachingContent.intermediate:
File system operations with proper error handling:

**Async/Await with fs.promises:**
```javascript
const fs = require('fs').promises;

async function readData() {
  try {
    const data = await fs.readFile('data.txt', 'utf8');
    console.log(data);
  } catch (err) {
    console.error('Error:', err);
  }
}
```

**Common Operations:**
```javascript
// Check if file exists
fs.access('file.txt', (err) => {
  if (err) console.log('File does not exist');
});

// Delete file
fs.unlink('file.txt', (err) => {
  if (err) throw err;
});
```

teachingContent.advanced:
Advanced file operations and streams:

**Streams for Large Files:**
```javascript
const fs = require('fs');

// Reading large files
const readStream = fs.createReadStream('large.txt');
readStream.on('data', (chunk) => {
  console.log('Chunk:', chunk);
});

// Piping streams
const readStream = fs.createReadStream('input.txt');
const writeStream = fs.createWriteStream('output.txt');
readStream.pipe(writeStream);
```

teachingContent.beginner:
**Express** makes building web servers easy!

**Basic Server:**
```javascript
const express = require('express');
const app = express();

app.get('/', (req, res) => {
  res.send('Hello World!');
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Routes:**
```javascript
app.get('/users', (req, res) => {
  res.json([{ name: 'John' }]);
});

app.post('/users', (req, res) => {
  res.json({ message: 'User created' });
});
```

teachingContent.intermediate:
Express.js for building RESTful APIs:

**Middleware:**
```javascript
const express = require('express');
const app = express();

// Built-in middleware
app.use(express.json());

// Custom middleware
app.use((req, res, next) => {
  console.log(`${req.method} ${req.url}`);
  next();
});

// Route handlers
app.get('/api/users/:id', (req, res) => {
  const { id } = req.params;
  res.json({ id, name: 'John' });
});
```

teachingContent.advanced:
Advanced Express patterns and error handling:

**Error Handling:**
```javascript
// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: err.message });
});

// Async error handling
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

app.get('/users', asyncHandler(async (req, res) => {
  const users = await User.find();
  res.json(users);
}));
```

teachingContent.beginner:
Node.js uses **asynchronous** code to handle multiple tasks.

**Callbacks:**
```javascript
fs.readFile('file.txt', (err, data) => {
  if (err) throw err;
  console.log(data);
});
```

**Promises:**
```javascript
fs.promises.readFile('file.txt')
  .then(data => console.log(data))
  .catch(err => console.error(err));
```

**Async/Await:**
```javascript
async function readData() {
  const data = await fs.promises.readFile('file.txt');
  console.log(data);
}
```

teachingContent.intermediate:
Modern async patterns in Node.js:

**Promise Chaining:**
```javascript
fetchUser()
  .then(user => fetchPosts(user.id))
  .then(posts => console.log(posts))
  .catch(err => console.error(err));
```

**Async/Await:**
```javascript
async function getData() {
  try {
    const user = await fetchUser();
    const posts = await fetchPosts(user.id);
    return posts;
  } catch (err) {
    console.error(err);
  }
}
```

teachingContent.advanced:
Advanced async patterns and error handling:

**Promise.all:**
```javascript
const [users, posts, comments] = await Promise.all([
  fetchUsers(),
  fetchPosts(),
  fetchComments()
]);
```

**Error Handling:**
```javascript
try {
  const data = await riskyOperation();
} catch (err) {
  if (err.code === 'ENOENT') {
    // Handle file not found
  } else {
    throw err;
  }
}
```
